/** Seuls les badges générés par l'interface échappent à la protection du tableau. */
function studioViewerRankMarker(element) {
  const marker = element?.closest("[data-studio-viewer-rank]");
  if (!marker || element.closest(STUDIO_VIEWER_RANK_USER_CONTENT_SELECTOR)) return null;
  return marker;
}

function studioTranslate(value) {
  if (!studioLocale().startsWith("en")) return value;
  if (STUDIO_ENGLISH[value]) return STUDIO_ENGLISH[value];
  const patterns = [
    [/^([\d\s\u00a0\u202f]+) diamant cumulé$/, (_, count) => `${count} cumulative diamond${count === "1" ? "" : "s"}`],
    [/^De ([\d\s\u00a0\u202f]+) à ([\d\s\u00a0\u202f]+) diamants cumulés$/, (_, minimum, maximum) => `From ${minimum} to ${maximum} cumulative diamonds`],
    [/^À partir de ([\d\s\u00a0\u202f]+) diamants cumulés$/, (_, minimum) => `At least ${minimum} cumulative diamonds`],
    [/^(\d+) messages? en rotation$/, (_, count) => `${count} rotating message${count === "1" ? "" : "s"}`],
    [/^(\d+) alias$/, (_, count) => `${count} alias${count === "1" ? "" : "es"}`],
    [/^Votre abonnement (Pro|Premium) s’arrêtera le$/, (_, tier) => `Your ${tier} subscription will end on`],
    [/^(pro|premium) · essai$/, (_, tier) => `${tier} · trial`],
    [/^(pro|premium) · offert$/, (_, tier) => `${tier} · gifted`],
    [/^(\d+) jeux?$/, (_, count) => `${count} game${count === "1" ? "" : "s"}`],
    [/^(\d+) prises? pilotables?$/, (_, count) => `${count} controllable plug${count === "1" ? "" : "s"}`],
    [/^(\d+) profils?$/, (_, count) => `${count} profile${count === "1" ? "" : "s"}`],
    [/^(\d+) règles? · espace de travail indépendant$/, (_, count) => `${count} rule${count === "1" ? "" : "s"} · independent workspace`],
    [/^(\d+) spectateurs? · page (\d+) \/ (\d+)$/, (_, count, page, pages) => `${count} viewer${count === "1" ? "" : "s"} · page ${page} / ${pages}`],
    [/^(\d+) utilisateurs? · page (\d+) \/ (\d+)$/, (_, count, page, pages) => `${count} user${count === "1" ? "" : "s"} · page ${page} / ${pages}`],
    [/^(\d+) blocages? · page (\d+) \/ (\d+)$/, (_, count, page, pages) => `${count} block${count === "1" ? "" : "s"} · page ${page} / ${pages}`],
    [/^(\d+) sélectionnés?$/, (_, count) => `${count} selected`],
    [/^([\d.,\s\u00a0kKMG]+) événements traités et ([\d.,\s\u00a0kKMG]+) actions exécutées pendant cette session\.$/, (_, events, actions) => `${events} events processed and ${actions} actions executed this session.`],
    [/^(\d+) caractères maximum$/, (_, count) => `${count} characters maximum`],
    [/^(\d+) mot\(s\) bloqué\(s\)$/, (_, count) => `${count} blocked word${count === "1" ? "" : "s"}`],
    [/^([\d.,\s\u00a0kKMG]+) pièces?$/, (_, count) => `${count} coin${count === "1" ? "" : "s"}`],
    [/^(\d+) JEUX COMMUNAUTAIRES$/, (_, count) => `${count} COMMUNITY GAMES`],
    [/^(\d+) interactions?$/, (_, count) => `${count} interaction${count === "1" ? "" : "s"}`],
    [/^(\d+) actions · profils illimités$/, (_, count) => `${count} actions · unlimited profiles`],
    [/^(\d+) \/ 3 actions · 1 profil$/, (_, count) => `${count} / 3 actions · 1 profile`],
    [/^jusqu’à 1 000 caractères$/, () => "up to 1,000 characters"],
    [/^LIVE · Écran (\d+)$/, (_, screen) => `LIVE · Screen ${screen}`],
    [/^Écran (\d+)$/, (_, screen) => `Screen ${screen}`],
    [/^Toutes les ([\d.,]+) (secondes?|minutes?|heures?)$/, (_, count, unit) => `Every ${count} ${({ seconde: "second", secondes: "seconds", minute: "minute", minutes: "minutes", heure: "hour", heures: "hours" })[unit]}`],
    [/^(\d+)s de cooldown$/, (_, seconds) => `${seconds}s cooldown`],
    [/^Toutes · (\d+)$/, (_, count) => `All · ${count}`],
    [/^(\d+) au hasard sur (\d+)$/, (_, count, total) => `${count} random actions out of ${total}`],
    [/^▶ Simuler le déclencheur (gift|like|follow|chat|share|subscribe|join)$/, (_, type) => `▶ Simulate ${type} trigger`]
  ];
  for (const [pattern, translate] of patterns) if (pattern.test(value)) return value.replace(pattern, translate);
  if (value.includes(" · ")) return value.split(" · ").map(studioTranslate).join(" · ");
  return value;
}

function applyStudioLanguage(root) {
  if (!root) return;
  syncStudioPreferences();
  const walker = document.createTreeWalker(root, NodeFilter.SHOW_TEXT);
  let node;
  while ((node = walker.nextNode())) {
    const viewerRank = studioViewerRankMarker(node.parentElement);
    if (node.parentElement?.closest(STUDIO_USER_CONTENT_SELECTOR) && !viewerRank) continue;
    const prior = studioTranslatedNodes.get(node);
    const original = prior && node.nodeValue === prior.translated ? prior.original : node.nodeValue;
    const trimmed = original.trim();
    let translation = studioTranslate(trimmed);
    if (viewerRank && studioLocale().startsWith("en")) translation = STUDIO_VIEWER_RANK_ENGLISH[trimmed] || translation;
    if (studioLocale().startsWith("en") && trimmed === "Hauteur" &&
      node.parentElement?.closest(".field")?.querySelector('[name="pitch"], [name="ttsPitch"]')) translation = "Pitch";
    if (studioLocale().startsWith("en") && trimmed === "EN COURS" && node.parentElement?.closest(".timers-data-table")) translation = "RUNNING";
    const translated = translation === trimmed ? original : original.replace(trimmed, translation);
    if (node.nodeValue !== translated) node.nodeValue = translated;
    studioTranslatedNodes.set(node, { original, translated });
  }
  root.querySelectorAll("[placeholder], [title], [aria-label]").forEach((element) => {
    const viewerRank = studioViewerRankMarker(element);
    if (element.closest(STUDIO_USER_CONTENT_SELECTOR) && !element.matches("textarea") && !viewerRank) return;
    const stored = studioTranslatedAttributes.get(element) || {};
    for (const attribute of ["placeholder", "title", "aria-label"]) {
      if (!element.hasAttribute(attribute)) continue;
      const current = element.getAttribute(attribute);
      const prior = stored[attribute];
      const original = prior && current === prior.translated ? prior.original : current;
      const translated = studioLocale().startsWith("en") ? attribute === "title" && viewerRank === element ? studioTranslate(original) : STUDIO_ENGLISH[original] || original : original;
      if (current !== translated) element.setAttribute(attribute, translated);
      stored[attribute] = { original, translated };
    }
    studioTranslatedAttributes.set(element, stored);
  });
}

const STUDIO_PREFERENCE_ACTIONS = new Set(["studio-toggle-language", "studio-toggle-light"]);

async function handleStudioPreferenceAction({ action }) {
  if (action === "studio-toggle-light") {
    studioLightMode = !studioLightMode;
    try { localStorage.setItem("shenpulse.light-mode", String(studioLightMode)); } catch {}
    syncStudioPreferences();
    return;
  }
  if (action === "studio-toggle-language") {
    studioLocaleOverride = studioLocale().startsWith("en") ? "fr-FR" : "en-US";
    try { localStorage.setItem("shenpulse.interface-locale", studioLocaleOverride); } catch {}
    if (isAccountAuthenticated()) acceptSnapshot(await api.saveSettings({ locale: studioLocaleOverride }));
    syncChrome();
    syncStudioPreferences();
    applyStudioLanguage(navigation);
    applyStudioLanguage(document.querySelector(".topbar"));
    applyStudioLanguage(content);
    if (dialog.open) applyStudioLanguage(dialog);
  }
}
